nota1 = float(input('Primeira nota: ')) #Pergunta a primeira nota escolar com float
nota2 = float(input('Segunda nota: ')) #Pergunta a segunda nota escolar também com float
media = (nota1 + nota2) / 2 #Faz o calculo da média, primeiro somando a primeira e a segunda nota e depois dividindo para armazenar o resultado final
print('A média do aluno é {}.'.format(media)) #Mostra o resultado com resposta final, ou seja, mostra a média final